SELECT 'gongkao', '舆情危机处理', 'kp-ms-emg-media', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "应急应变：舆情危机处理"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "黄金四小时。态度诚恳，信息公开，用真相击碎谣言。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、处置流程"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【迅速介入，成立专班】：切断谣言源头，立刻成立由多部门组成的舆情调查专班介入调查。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【初步回应，稳定情绪】：在官方账号第一时间发布“已关注到此事，正在核实调查，请大家不信谣不传谣”的通报，表明政府绝不护短的态度。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【查明真相，分类处置】：如果爆料是假的，公布完整监控视频和证据链辟谣，并追究造谣者法律责任。如果爆料是真的，立刻对涉事人员停职调查，公布顶格处罚结果。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【权威发布，重塑形象】：召开新闻发布会，由一把手出面鞠躬道歉，通报处理结果，并公布后续的整改措施和群众监督举报电话。"}]}]}]}]}$$ AS jsonb), NULL, '舆情危机处理的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "应急应变", "舆情处理"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_emg_media", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
